const me = $('Threads Kimlik Doğrula').first()?.json || {};
const posts = Array.isArray($json.data) ? $json.data : [];
const nowSec = Math.floor(Date.now() / 1000);
const eligible = posts.filter((p) => p && p.id && (!p.timestamp || (nowSec - Math.floor(Date.parse(p.timestamp) / 1000)) <= 7 * 86400)).slice(0, 5);
return eligible.map((p) => ({
  json: {
    threadsUserId: String(me.id || '29067357699551135'),
    myUsername: String(me.username || 'socialora1').toLowerCase(),
    rootId: String(p.id),
    rootText: String(p.text || ''),
    rootPermalink: String(p.permalink || ''),
  }
}));

const roots = $('Son 5 Gönderiyi Hazırla').all();
const replyPages = $input.all();
const nowSec = Math.floor(Date.now() / 1000);
const todayTrt = new Date((nowSec + 3 * 3600) * 1000).toISOString().slice(0, 10);

const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const fs = require('fs');
const nodePath = require('path');

const readFull = () => {
  try {
    if (!fs.existsSync(GROWTH_PATH)) return {};
    return JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8')) || {};
  } catch { return {}; }
};

const writeThreadsReplies = (nextTr) => {
  const full = readFull();
  full.threadsReplies = nextTr;
  fs.mkdirSync(nodePath.dirname(GROWTH_PATH), { recursive: true });
  const tmp = GROWTH_PATH + '.tmp.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8);
  fs.writeFileSync(tmp, JSON.stringify(full, null, 2), 'utf8');
  fs.renameSync(tmp, GROWTH_PATH);
};

const full = readFull();
const diskTr = (full && typeof full.threadsReplies === 'object' && full.threadsReplies) ? full.threadsReplies : {};
const sd = $getWorkflowStaticData('global');

if (!Array.isArray(sd.repliedIds)) sd.repliedIds = [];
if (Array.isArray(diskTr.repliedIds)) {
  sd.repliedIds = [...new Set([...sd.repliedIds, ...diskTr.repliedIds])].slice(-300);
}
const sdCount = sd.dayTrt === todayTrt ? Number(sd.countToday || 0) : 0;
const diskCount = diskTr.dayTrt === todayTrt ? Number(diskTr.countToday || 0) : 0;
sd.dayTrt = todayTrt;
sd.countToday = Math.max(sdCount, diskCount);
sd.lastPublishedAt = Math.max(Number(sd.lastPublishedAt || 0), Number(diskTr.lastPublishedAt || 0));

const liveHasReplies = new Map();
for (let i = 0; i < replyPages.length; i++) {
  const rows = Array.isArray(replyPages[i]?.json?.data) ? replyPages[i].json.data : [];
  for (const r of rows) {
    if (r && r.id) liveHasReplies.set(String(r.id), r.has_replies === true);
  }
}

const repliedSet = new Set(sd.repliedIds);
let approvals = Array.isArray(diskTr.pendingApprovals) ? diskTr.pendingApprovals : [];
let changed = false;

for (const ap of approvals) {
  if (!ap || !ap.commentId) continue;
  const cid = String(ap.commentId);
  if (ap.status === 'skipped' && !repliedSet.has(cid)) {
    repliedSet.add(cid);
    sd.repliedIds.push(cid);
    changed = true;
  }
  if ((ap.status === 'pending_approval' || ap.status === 'approved') && (repliedSet.has(cid) || liveHasReplies.get(cid) === true)) {
    ap.status = 'already_replied';
    repliedSet.add(cid);
    if (!sd.repliedIds.includes(cid)) sd.repliedIds.push(cid);
    changed = true;
  }
}

const pruned = approvals.filter((ap) => ap && (nowSec - Number(ap.draftedAt || nowSec) <= 7 * 86400)).slice(-80);
if (pruned.length !== approvals.length) changed = true;
approvals = pruned;

if (changed) {
  sd.repliedIds = sd.repliedIds.slice(-300);
  writeThreadsReplies({
    ...diskTr,
    repliedIds: sd.repliedIds,
    dayTrt: sd.dayTrt,
    countToday: sd.countToday,
    lastPublishedAt: sd.lastPublishedAt,
    pendingApprovals: approvals,
  });
}

if (sd.countToday >= 12) return [];

const readyToPublish = approvals
  .filter((ap) => {
    if (!ap || !ap.commentId || !ap.replyText) return false;
    const cid = String(ap.commentId);
    if (repliedSet.has(cid) || liveHasReplies.get(cid) === true) return false;
    if (ap.status === 'approved') return true;
    if (ap.status === 'pending_approval' && (nowSec - Number(ap.draftedAt || 0) >= 900)) return true;
    return false;
  })
  .sort((a, b) => Number(a.draftedAt || 0) - Number(b.draftedAt || 0));

if (readyToPublish.length > 0) {
  const item = readyToPublish[0];
  const triggerReason = item.status === 'approved' ? 'manual_approved' : 'auto_timeout_900s';
  return [{
    json: {
      mode: 'publish_ready',
      triggerReason,
      approvalId: String(item.approvalId || item.commentId),
      threadsUserId: String(item.threadsUserId || roots[0]?.json?.threadsUserId || '29067357699551135'),
      myUsername: String(roots[0]?.json?.myUsername || 'socialora1'),
      rootId: String(item.rootId || ''),
      rootText: String(item.rootText || ''),
      commentId: String(item.commentId),
      commenter: String(item.commenter || ''),
      commentText: String(item.commentText || ''),
      replyText: String(item.replyText || ''),
      draftedAt: Number(item.draftedAt || nowSec),
    }
  }];
}

const pendingIds = new Set(approvals.map((ap) => String(ap.commentId)));
const candidates = [];
for (let i = 0; i < replyPages.length; i++) {
  const root = roots[i]?.json || {};
  const rows = Array.isArray(replyPages[i]?.json?.data) ? replyPages[i].json.data : [];
  for (const r of rows) {
    if (!r || !r.id) continue;
    const cid = String(r.id);
    const uname = String(r.username || '').toLowerCase();
    if (!uname || uname === (root.myUsername || 'socialora1')) continue;
    if (repliedSet.has(cid) || pendingIds.has(cid) || r.has_replies === true) continue;
    const txt = String(r.text || '').trim();
    if (txt.length < 3 || /https?:\/\/|t\.me\/|crypto|airdrop|whatsapp/i.test(txt)) continue;
    const ts = r.timestamp ? Math.floor(Date.parse(r.timestamp) / 1000) : nowSec;
    if (nowSec - ts > 172800 || nowSec - ts < 90) continue;
    candidates.push({
      threadsUserId: root.threadsUserId,
      myUsername: root.myUsername,
      rootId: root.rootId,
      rootText: root.rootText,
      rootPermalink: root.rootPermalink,
      commentId: cid,
      commenter: uname,
      commentText: txt,
      commentTs: ts,
      commentPermalink: String(r.permalink || ''),
    });
  }
}

if (candidates.length === 0) return [];
candidates.sort((a, b) => a.commentTs - b.commentTs);

const modelsCacheValid = Boolean(
  Array.isArray(sd.cachedModels) &&
  sd.cachedModels.length > 0 &&
  Number(sd.modelsCachedAt || 0) > 0 &&
  (nowSec - Number(sd.modelsCachedAt || 0) < 21600)
);

return [{ json: { mode: 'draft_new', modelsCacheValid, ...candidates[0] } }];

const src = $('Bekleyen Onay & Yorum Seç').first()?.json;
if (!src || src.mode !== 'draft_new') return [];

const sd = $getWorkflowStaticData('global');
const nowSec = Math.floor(Date.now() / 1000);
const disc = $input.first()?.json || {};
const rawModels = Array.isArray(disc.models) ? disc.models : [];
let candidates = [];
if (rawModels.length > 0) {
  candidates = rawModels
    .filter((m) => {
      const name = String(m.name || '').replace(/^models\//, '');
      const methods = Array.isArray(m.supportedGenerationMethods) ? m.supportedGenerationMethods : [];
      return name.includes('flash') && methods.includes('generateContent') && !/(image|tts|live|audio|preview|exp|thinking|robotics|computer|embedding)/i.test(name);
    })
    .map((m) => String(m.name || '').replace(/^models\//, ''));
  if (candidates.length > 0) {
    sd.cachedModels = candidates;
    sd.modelsCachedAt = nowSec;
  }
} else if (Array.isArray(sd.cachedModels) && sd.cachedModels.length > 0) {
  candidates = sd.cachedModels;
}

const defaults = ['gemini-3.5-flash-lite', 'gemini-2.5-flash-lite', 'gemini-2.5-flash'];
const ordered = [...new Set([...candidates, ...defaults])];
const primaryModel = ordered.find((n) => n === 'gemini-3.5-flash-lite') || ordered[0];
const fallbackModel = ordered.find((n) => n === 'gemini-2.5-flash-lite') || ordered.find((n) => n !== primaryModel) || primaryModel;

const GOLDEN_RULES = [
  'STRICT COMMENT RULES:',
  '- NEVER use marketing cliches, enthusiasm fillers, fake stats, or links ("Great post!", "Totally agree!", "We tested this on 20 accounts and boosted retention by 50%!", "elevate", "game-changer", "unlock", "skyrocket", "delve", "realm", "unleash", "tapestry", "let us dive in", "in conclusion").',
  '- Read the commenter\'s specific workflow or observation; complete a subtle practical distinction, overlooked checkpoint, or design nuance.',
  '- Write 2 to 3 sentences (30 to 55 words) in 100% natural English ONLY (never Turkish), calm, intelligent peer-to-peer expert colleague tone.',
  '- ZERO emojis, NO markdown, NO hashtags, NO em-dashes (U+2014), NO en-dashes (U+2013), NO bullet characters (U+2022).',
  '',
  '5 GOLDEN REFERENCE EXAMPLES (match this exact tone, rhythm, and practical specificity):',
  '[Example 1 - Workflow / Automation]: "Starting with two makes the weak link much easier to find. One extra checkpoint before publishing helps too: moving the right file is one test; moving the approved version is another. A shared draft/approved status can stop a perfectly working automation from sending out unfinished work."',
  '[Example 2 - App / Productivity]: "One design choice that could make this easier: let a handwritten note turn into a calendar block without making people enter it again. The real friction is often copying the same plan into two places. Can Scribble carry unfinished items forward without duplicating them?"',
  '[Example 3 - Dialogue Continuation]: "Then you were two years ahead of my suggestion. Moving the original handwriting, rather than creating another task to type out, is exactly the distinction I meant. \'Manana-eraser\' sounds much kinder than \'Procrastinator\', too. Thanks for explaining how it works."',
  '[Example 4 - Tools / Pricing / Queue]: "I\'d wait unless there\'s a deadline. Before paying to skip the queue, I\'d check the watermark, download resolution, and whether a failed generation gets your credit back. Getting to the front of the line isn\'t much help if the export isn\'t usable."',
  '[Example 5 - Prompts / Settings / Design]: "A small detail that helps when sharing prompts: include the model/version, aspect ratio and any reference image settings too. Otherwise someone can copy every word and still be testing a very different setup."',
].join('\n');

const prompt = `Our post on Threads:\n"${src.rootText}"\n\n@${src.commenter} replied:\n"${src.commentText}"\n\n${GOLDEN_RULES}\n\nWrite ONLY the reply text in natural English (2 to 3 sentences, 30 to 55 words, no quotes around output).`;
const buildBody = (model) => {
  const genCfg = { temperature: 0.65, topP: 0.9, maxOutputTokens: 260 };
  if (String(model).includes('2.5')) genCfg.thinkingConfig = { thinkingBudget: 0 };
  return {
    system_instruction: { parts: [{ text: 'You are the founder/editor running @socialora1 on Threads. Always write strictly in natural English only (never Turkish), 2 to 3 sentences (30 to 55 words), calm peer colleague tone matching the 5 golden reference examples. Plain text only, zero emojis, zero links, zero em/en-dashes or bullets.' }] },
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    generationConfig: genCfg,
  };
};
return [{ json: { ...src, primaryModel, fallbackModel, requestBody: buildBody(primaryModel), fallbackBody: buildBody(fallbackModel) } }];

const src = $('Yanıt Promptu Hazırla').first()?.json;
const raw = $json.candidates?.[0]?.content?.parts?.map((p) => p.text || '').join('') || '';
const clean = raw
  .replace(/\s*[\u2014\u2013]\s*/g, ', ')
  .replace(/[*_`#\u2022]/g, '')
  .replace(/[\u{1F300}-\u{1FAFF}]/gu, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 420);
const bannedCliche = /\b(?:elevate your game|game-changer|unlock|skyrocket|let's dive in|delve|realm|unleash|tapestry|great post|totally agree)\b/i;
if (!src || clean.length < 4 || /[çğıöşüÇĞİÖŞÜ]/.test(clean) || bannedCliche.test(clean)) return [];
return [{ json: { ...src, replyText: clean } }];

const info = $('Yanıtı Temizle').first()?.json || {};
if (!info.commentId || !info.replyText) return [];

const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const fs = require('fs');
const nodePath = require('path');

let full = {};
try {
  if (fs.existsSync(GROWTH_PATH)) full = JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8')) || {};
} catch { full = {}; }

const prev = (full && typeof full.threadsReplies === 'object' && full.threadsReplies) ? full.threadsReplies : {};
const approvals = Array.isArray(prev.pendingApprovals) ? prev.pendingApprovals : [];
const approvalId = String(info.commentId);
const nowSec = Math.floor(Date.now() / 1000);

if (!approvals.some((a) => String(a.commentId) === String(info.commentId))) {
  approvals.push({
    approvalId,
    commentId: String(info.commentId),
    threadsUserId: String(info.threadsUserId || '29067357699551135'),
    rootId: String(info.rootId || ''),
    rootText: String(info.rootText || '').slice(0, 180),
    commenter: String(info.commenter || ''),
    commentText: String(info.commentText || '').slice(0, 300),
    commentPermalink: String(info.commentPermalink || ''),
    replyText: String(info.replyText || ''),
    draftedAt: nowSec,
    expiresAt: nowSec + 900,
    status: 'pending_approval',
  });
}

full.threadsReplies = {
  ...prev,
  repliedIds: Array.isArray(prev.repliedIds) ? prev.repliedIds.slice(-300) : [],
  pendingApprovals: approvals.slice(-80),
};

fs.mkdirSync(nodePath.dirname(GROWTH_PATH), { recursive: true });
const tmp = GROWTH_PATH + '.tmp.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8);
fs.writeFileSync(tmp, JSON.stringify(full, null, 2), 'utf8');
fs.renameSync(tmp, GROWTH_PATH);

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const htmlText = [
  '💬 <b>Yeni Threads Yorumu (Onay Bekliyor)</b>',
  '',
  '<b>Yorumcu:</b> @' + esc(info.commenter),
  '<b>Gönderimiz:</b> ' + esc(String(info.rootText || '').slice(0, 110)),
  '<b>Gelen Yorum:</b> ' + esc(String(info.commentText || '').slice(0, 200)),
  '<b>Hazırlanan Yanıt:</b> ' + esc(info.replyText),
  '',
  'Onaylamak için: /approve_' + esc(approvalId),
  'İptal etmek için: /skip_' + esc(approvalId),
  '',
  '<i>15 dakika (900 sn) içinde müdahale olmazsa bir sonraki kontrolde otomatik yayınlanır.</i>'
].join('\n');

return [{ json: { ok: true, approvalId, commentId: info.commentId, htmlText } }];

const GROWTH_PATH = 'C:\\Users\\idoca\\.n8n\\socialora-growth.json';
const fs = require('fs');
const nodePath = require('path');

const info = $('Bekleyen Onay & Yorum Seç').first()?.json || {};
const nowSec = Math.floor(Date.now() / 1000);
const todayTrt = new Date((nowSec + 3 * 3600) * 1000).toISOString().slice(0, 10);

let full = {};
try {
  if (fs.existsSync(GROWTH_PATH)) full = JSON.parse(fs.readFileSync(GROWTH_PATH, 'utf8')) || {};
} catch { full = {}; }

const prev = (full && typeof full.threadsReplies === 'object' && full.threadsReplies) ? full.threadsReplies : {};
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.repliedIds)) sd.repliedIds = [];
const mergedIds = [...new Set([...(Array.isArray(prev.repliedIds) ? prev.repliedIds : []), ...sd.repliedIds, ...(info.commentId ? [String(info.commentId)] : [])])].slice(-300);

const prevDiskCount = prev.dayTrt === todayTrt ? Number(prev.countToday || 0) : 0;
const prevSdCount = sd.dayTrt === todayTrt ? Number(sd.countToday || 0) : 0;
const nextCount = Math.max(prevDiskCount, prevSdCount) + 1;

const nextStatus = info.triggerReason === 'manual_approved' ? 'published' : 'auto_published';
const approvals = (Array.isArray(prev.pendingApprovals) ? prev.pendingApprovals : []).map((ap) => {
  if (ap && String(ap.commentId) === String(info.commentId)) {
    return {
      ...ap,
      status: nextStatus,
      publishedAt: nowSec,
      publishedReplyId: String($json.id || ''),
    };
  }
  return ap;
}).slice(-80);

const nextObj = {
  ...prev,
  repliedIds: mergedIds,
  dayTrt: todayTrt,
  countToday: nextCount,
  lastPublishedAt: nowSec,
  pendingApprovals: approvals,
};

full.threadsReplies = nextObj;
fs.mkdirSync(nodePath.dirname(GROWTH_PATH), { recursive: true });
const tmp = GROWTH_PATH + '.tmp.' + Date.now() + '.' + Math.random().toString(36).slice(2, 8);
fs.writeFileSync(tmp, JSON.stringify(full, null, 2), 'utf8');
fs.renameSync(tmp, GROWTH_PATH);

sd.repliedIds = nextObj.repliedIds;
sd.dayTrt = nextObj.dayTrt;
sd.countToday = nextObj.countToday;
sd.lastPublishedAt = nextObj.lastPublishedAt;

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const title = info.triggerReason === 'manual_approved'
  ? '✅ <b>Onaylanan Threads Yanıtı Yayınlandı</b>'
  : '⏱ <b>15 Dk Onay Süresi Doldu, Threads Yanıtı Otomatik Yayınlandı</b>';

return [{
  json: {
    ok: true,
    publishedReplyId: $json.id || null,
    repliedToComment: info.commentId,
    commenter: info.commenter,
    triggerReason: info.triggerReason,
    countToday: sd.countToday,
    htmlText: title + ' (@' + esc(info.commenter) + ')\n\n<b>Gelen Yorum:</b> ' + esc(String(info.commentText || '').slice(0, 160)) + '\n<b>Yayınlanan Yanıt:</b> ' + esc(String(info.replyText || ''))
  }
}];
